steps.script:
for uid in GameState.state.units:
	var u = GameState.state.units[uid]
	if int(u.get("owner", 0)) == 2:
		for m in u.models:
			m["wounds"] = 99
			m["current_wounds"] = 99
return true

var ph = PhaseManager.get_current_phase_instance()
if ph.get("awaiting_ability_reroll"):
	ph.execute_action({"type": "DECLINE_ABILITY_REROLL", "actor_unit_id": "U_WARBOSS_IN_MEGA_ARMOUR_A", "player": 1})
if ph.get("awaiting_reroll_decision"):
	ph.execute_action({"type": "DECLINE_COMMAND_REROLL", "actor_unit_id": "U_WARBOSS_IN_MEGA_ARMOUR_A", "player": 1})
for c in tree.root.get_children():
	if c is Window and c != tree.root and str(c.name) != "StratagemDialog":
		c.hide()
		c.queue_free()
var dist = int(ph.pending_charges["U_WARBOSS_IN_MEGA_ARMOUR_A"]["distance"])
print("[wp-o6] charge roll ", dist)
return dist >= 4

var ph = PhaseManager.get_current_phase_instance()
var dist = int(ph.pending_charges["U_WARBOSS_IN_MEGA_ARMOUR_A"]["distance"])
var mv = AIDecisionMaker._compute_charge_move(GameState.create_snapshot(), "U_WARBOSS_IN_MEGA_ARMOUR_A", dist, ["U_CUSTODIAN_GUARD_B"], 1)
if str(mv.get("type", "")) != "APPLY_CHARGE_MOVE":
	return "NO_MOVE"
mv["player"] = 1
var r = NetworkIntegration.route_action(mv)
return r.get("success", false)
